import 'package:print_bluetooth_thermal/print_bluetooth_thermal.dart';

Future<void> printDemo() async {
  final bool btOn = await PrintBluetoothThermal.bluetoothEnabled;
  if (!btOn) return;
  final printers = await PrintBluetoothThermal.pairedBluetooths;
  if (printers.isEmpty) return;
  final mac = printers.first.macAdress;
  final connected = await PrintBluetoothThermal.connect(macPrinterAddress: mac);
  if (connected) {
    await PrintBluetoothThermal.writeString(printText: PrintTextSize(size: 2, text: 'Hello world'));
    await PrintBluetoothThermal.disconnect;
  }
}
